/* DAWAH X — darimi, অধ্যায় 13 · খণ্ড 13 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][13]=[[2401,2401,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏حَرِيزِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عَوْفٍ وَهُوَ عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هِنْدٍ الْبَجَلِيِّ ‏ ‏وَكَانَ مِنْ السَّلَفِ ‏ ‏قَالَ ‏ ‏تَذَاكَرُوا الْهِجْرَةَ عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَهُوَ عَلَى سَرِيرِهِ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَنْقَطِعُ الْهِجْرَةُ حَتَّى تَنْقَطِعَ التَّوْبَةُ ثَلَاثًا وَلَا تَنْقَطِعُ التَّوْبَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ‏","","",""],[2402,2402,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏","","",""],[2403,2403,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَمِيرِ عَشَرَةٍ إِلَّا يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ ‏ ‏مَغْلُولَةٌ ‏ ‏يَدَاهُ إِلَى عُنُقِهِ أَطْلَقَهُ الْحَقُّ أَوْ ‏ ‏أَوْبَقَهُ ‏","","",""],[2404,2404,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[2405,2405,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ يُؤَيِّدُ هَذَا الدِّينَ بِالرَّجُلِ الْفَاجِرِ ‏","","",""],[2406,2406,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنِي ‏ ‏أَزْهَرُ بْنُ عَبْدِ اللَّهِ الْحَرَازِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ هُوَ عَبْدُ اللَّهِ بْنُ لُحَيٍّ الْهَوْزَنِيِّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِينَا فَقَالَ ‏ ‏أَلَا إِنَّ مَنْ كَانَ قَبْلَكُمْ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏افْتَرَقُوا عَلَى ثِنْتَيْنِ وَسَبْعِينَ مِلَّةً وَإِنَّ هَذِهِ الْأُمَّةَ سَتَفْتَرِقُ عَلَى ثَلَاثٍ وَسَبْعِينَ اثْنَتَانِ وَسَبْعُونَ فِي النَّارِ وَوَاحِدَةٌ فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْحَرَازُ ‏ ‏قَبِيلَةٌ مِنْ أَهْلِ ‏ ‏الْيَمَنِ ‏","","",""],[2407,2407,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَجَاءٍ الْعُطَارِدِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَرْوِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ فَإِنَّهُ لَيْسَ مِنْ أَحَدٍ يُفَارِقُ الْجَمَاعَةَ شِبْرًا فَيَمُوتُ إِلَّا مَاتَ مِيتَةً جَاهِلِيَّةً ‏","","",""],[2408,2408,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَلَّ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏","","",""],[2409,2409,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ كَانَ ‏ ‏مُحَمَّدُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَهُوَ عِنْدَهُ فِي وَفْدٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا الْأَمْرَ فِي ‏ ‏قُرَيْشٍ ‏ ‏لَا يُعَادِيهِمْ أَحَدٌ إِلَّا كَبَّهُ اللَّهُ عَلَى وَجْهِهِ مَا أَقَامُوا الدِّينَ ‏","","",""],[2410,2410,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَأَشْجَعُ ‏ ‏لَيْسَ لَهُمْ ‏ ‏مَوْلًى ‏ ‏دُونَ اللَّهِ وَرَسُولِهِ ‏","","",""],[2411,2411,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرَأَيْتُمْ إِنْ كَانَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏خَيْرًا مِنْ الْحَلِيفَيْنِ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏أَتُرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ فَإِنَّهُمْ خَيْرٌ مِنْهُمْ قَالَ أَفَرَأَيْتُمْ إِنْ كَانَتْ ‏ ‏مُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏خَيْرًا مِنْ ‏ ‏تَمِيمٍ ‏ ‏وَعَامِرِ بْنِ صَعْصَعَةَ ‏ ‏وَمَدَّ بِهَا صَوْتَهُ ‏ ‏أَتُرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ فَإِنَّهُمْ خَيْرٌ مِنْهُمْ ‏","","",""],[2412,2412,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ هُوَ ابْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏","","",""],[2413,2413,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَعُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[2414,2414,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قِيلَ ‏ ‏لِشَرِيكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏لَا حِلْفَ فِي الْإِسْلَامِ وَفِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الْإِسْلَامُ إِلَّا شِدَّةً وَجِدَّةً ‏","","",""],[2415,2415,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِمُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏أَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَذْكُرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلنُّعْمَانِ بْنِ مُقَرِّنٍ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ قَالَ نَعَمْ ‏","","",""],[2416,2416,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَوْلَى ‏ ‏الْقَوْمِ مِنْهُمْ وَحَلِيفُ الْقَوْمِ مِنْهُمْ وَابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏","","",""],[2417,2417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ تَحْتَ نَاقَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ يَقُولُ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ انْتَمَى إِلَى غَيْرِ ‏ ‏مَوَالِيهِ ‏ ‏رَغْبَةً عَنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏","","",""],[2418,2418,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏وَأَبِي بَكْرَةَ ‏ ‏أَنَّهُمَا حَدَّثَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏","","",""],[2419,2419,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ وَبَيْنَهُمَا ‏ ‏مُتَشَابِهَاتٌ ‏ ‏لَا يَعْلَمُهَا كَثِيرٌ مِنْ النَّاسِ فَمَنْ اتَّقَى ‏ ‏الشُّبُهَاتِ ‏ ‏اسْتَبْرَأَ لِعِرْضِهِ وَدِينِهِ وَمَنْ وَقَعَ فِي ‏ ‏الشُّبُهَاتِ ‏ ‏وَقَعَ فِي الْحَرَامِ كَالرَّاعِي ‏ ‏يَرْعَى حَوْلَ الْحِمَى فَيُوشِكُ أَنْ يُوَاقِعَهُ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلَا وَهِيَ الْقَلْبُ ‏","","",""],[2420,2420,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ السَّعْدِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏مَا تَحْفَظُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَأَلَهُ رَجُلٌ عَنْ مَسْأَلَةٍ لَا أَدْرِي مَا هِيَ فَقَالَ ‏ ‏دَعْ مَا ‏ ‏يَرِيبُكَ ‏ ‏إِلَى مَا لَا ‏ ‏يَرِيبُكَ ‏","","",""],[2421,2421,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الزُّبَيْرِ أَبِي عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عَبْدِ اللَّهِ بْنِ مِكْرَزٍ الْفِهْرِيِّ ‏ ‏عَنْ ‏ ‏وَابِصَةَ بْنِ مَعْبَدٍ الْأَسَدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِوَابِصَةَ ‏ ‏جِئْتَ تَسْأَلُ عَنْ الْبِرِّ وَالْإِثْمِ قَالَ قُلْتُ نَعَمْ قَالَ فَجَمَعَ أَصَابِعَهُ فَضَرَبَ بِهَا صَدْرَهُ وَقَالَ اسْتَفْتِ نَفْسَكَ اسْتَفْتِ قَلْبَكَ يَا ‏ ‏وَابِصَةُ ‏ ‏ثَلَاثًا الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَاطْمَأَنَّ إِلَيْهِ الْقَلْبُ وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ ‏","","",""],[2422,2422,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُرَّةَ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ آخِذًا بِزِمَامِ نَاقَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَوْسَطِ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏ ‏أَذُودُ النَّاسَ عَنْهُ فَقَالَ ‏ ‏أَلَا إِنَّ كُلَّ رِبًا فِي الْجَاهِلِيَّةِ مَوْضُوعٌ أَلَا وَإِنَّ اللَّهَ قَدْ قَضَى أَنَّ أَوَّلَ رِبًا يُوضَعُ رِبَا ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏لَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ ‏","","",""],[2423,2423,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُزَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا وَمُؤْكِلَهُ ‏","","",""],[2424,2424,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَأْتِيَنَّ زَمَانٌ لَا ‏ ‏يُبَالِي ‏ ‏الْمَرْءُ بِمَا أَخَذَ الْمَالَ بِحَلَالٍ أَمْ بِحَرَامٍ ‏","","",""],[2425,2425,"","","‏ ‏أَخْبَرَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَقَّ مَا يَأْكُلُ الرَّجُلُ مِنْ أَطْيَبِ كَسْبِهِ وَإِنَّ وَلَدَهُ مِنْ أَطْيَبِ كَسْبِهِ ‏","","",""],[2426,2426,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ هُوَ ابْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَقَالَ يَا مَعْشَرَ التُّجَّارِ حَتَّى إِذَا ‏ ‏اشْرَأَبُّوا قَالَ ‏ ‏التُّجَّارُ يُحْشَرُونَ يَوْمَ الْقِيَامَةِ فُجَّارًا إِلَّا مَنْ اتَّقَى وَبَرَّ وَصَدَقَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏كَانَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏يَقُولُ ‏ ‏عُبَيْدُ اللَّهِ بْنُ رِفَاعَةَ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏إِسْمَعِيلُ بْنُ عُبَيْدِ بْنِ رِفَاعَةَ ‏","","",""],[2427,2427,"","","‏ ‏أَخْبَرَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏التَّاجِرُ الصَّدُوقُ الْأَمِينُ مَعَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏لَا عِلْمَ لِي بِهِ إِنَّ ‏ ‏الْحَسَنَ ‏ ‏سَمِعَ مِنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَقَالَ ‏ ‏أَبُو حَمْزَةَ ‏ ‏هَذَا هُوَ صَاحِبُ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَهُوَ ‏ ‏مَيْمُونٌ الْأَعْوَرُ ‏","","",""],[2428,2428,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[2429,2429,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَحْيَى بْنُ الْمُتَوَكِّلِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْقَاسِمُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِطَعَامٍ بِسُوقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَأَعْجَبَهُ حُسْنُهُ فَأَدْخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فِي جَوْفِهِ فَأَخْرَجَ شَيْئًا لَيْسَ كَالظَّاهِرِ فَأَفَّفَ بِصَاحِبِ الطَّعَامِ ثُمَّ قَالَ ‏ ‏لَا غِشَّ بَيْنَ الْمُسْلِمِينَ مَنْ غَشَّنَا فَلَيْسَ مِنَّا ‏","","",""],[2430,2430,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ يُقَالُ هَذِهِ غَدْرَةُ فُلَانٍ ‏","","",""],[2431,2431,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏مَعْمَرِ بْنِ عَبْدِ اللَّهِ بْنِ نَافِعِ بْنِ نَضْلَةَ الْعَدَوِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يَحْتَكِرُ ‏ ‏إِلَّا خَاطِئٌ ‏ ‏مَرَّتَيْنِ ‏","","",""],[2432,2432,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَالِبُ مَرْزُوقٌ ‏ ‏وَالْمُحْتَكِرُ ‏ ‏مَلْعُونٌ ‏","","",""],[2433,2433,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَثَابِتٍ ‏ ‏وَقَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏غَلَا السِّعْرُ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّاسُ يَا رَسُولَ اللَّهِ غَلَا السِّعْرُ فَسَعِّرْ لَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ هُوَ الْخَالِقُ الْقَابِضُ الْبَاسِطُ الرَّازِقُ الْمُسَعِّرُ وَإِنِّي أَرْجُو أَنْ أَلْقَى رَبِّي وَلَيْسَ أَحَدٌ مِنْكُمْ يَطْلُبُنِي بِمَظْلَمَةٍ ظَلَمْتُهَا إِيَّاهُ بِدَمٍ وَلَا مَالٍ ‏","","",""],[2434,2434,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏أَنَّ ‏ ‏حُذَيْفَةَ ‏ ‏حَدَّثَهُمْ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَلَقَّتْ الْمَلَائِكَةُ رُوحَ رَجُلٍ مِمَّنْ قَبْلَكُمْ فَقَالُوا عَمِلْتَ مِنْ الْخَيْرِ شَيْئًا فَقَالَ لَا قَالُوا تَذَكَّرْ قَالَ كُنْتُ أُدَايِنُ النَّاسَ فَآمُرُ فِتْيَانِي أَنْ يُنْظِرُوا الْمُعْسِرَ وَيَتَجَاوَزُوا عَنْ الْمُوسِرِ قَالَ قَالَ اللَّهُ تَجَاوَزُوا عَنْهُ ‏","","",""],[2435,2435,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا وَإِنْ كَذَبَا وَكَتَمَا ‏ ‏مُحِقَ ‏ ‏بَرَكَةُ بَيْعِهِمَا ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِإِسْنَادِهِ مِثْلَهُ ‏","","",""],[2436,2436,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْبَيِّعَانِ إِذَا اخْتَلَفَا وَالْبَيْعُ قَائِمٌ بِعَيْنِهِ وَلَيْسَ بَيْنَهُمَا ‏ ‏بَيِّنَةٌ ‏ ‏فَالْقَوْلُ مَا قَالَ الْبَائِعُ أَوْ يَتَرَادَّانِ الْبَيْعَ ‏","","",""],[2437,2437,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَبِيعَ عَلَى بَيْعِ أَخِيهِ حَتَّى يَتْرُكَهُ ‏","","",""],[2438,2438,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُهْدَةُ الرَّقِيقِ ثَلَاثَةُ أَيَّامٍ ‏","","",""],[2439,2439,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُهْدَةُ الرَّقِيقِ ثَلَاثٌ ‏ ‏فَفَسَّرَهُ ‏ ‏قَتَادَةُ ‏ ‏إِنْ وَجَدَ فِي الثَّلَاثِ عَيْبًا رَدَّهُ بِغَيْرِ بَيِّنَةٍ وَإِنْ وَجَدَهُ بَعْدَ ثَلَاثٍ لَمْ يَرُدَّهُ إِلَّا بِبَيِّنَةٍ ‏","","",""],[2440,2440,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ هُوَ ابْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏أَوْ ‏ ‏لَقْحَةً ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ بِالْخِيَارِ ثَلَاثَةَ أَيَّامٍ فَإِنْ رَدَّهَا رَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ لَا ‏ ‏سَمْرَاءَ ‏","","",""],[2441,2441,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى الْقَطَّانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْغَرَرِ ‏","","",""],[2442,2442,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ حَتَّى يَبْدُوَ صَلَاحُهَا نَهَى الْبَائِعَ وَالْمُشْتَرِيَ ‏","","",""],[2443,2443,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ابْتَاعَ ثَمَرَةً فَأَصَابَتْهُ ‏ ‏جَائِحَةٌ ‏ ‏فَلَا يَأْخُذَنَّ مِنْهُ شَيْئًا بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ ‏","","",""],[2444,2444,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْمُحَاقَلَةُ بَيْعُ الزَّرْعِ ‏ ‏بِالْبُرِّ ‏ ‏وَقَالُوا كَذَلِكَ يَقُولُ ‏ ‏ابْنُ الْمُسَيَّبِ ‏","","",""],[2445,2445,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِالتَّمْرِ وَالرُّطَبِ وَلَمْ يُرَخِّصْ فِي غَيْرِ ذَلِكَ ‏","","",""],[2446,2446,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ ‏","","",""],[2447,2447,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏سَلَفٍ ‏ ‏وَبَيْعٍ ‏ ‏وَعَنْ شَرْطَيْنِ فِي بَيْعٍ وَعَنْ ‏ ‏رِبْحِ ‏ ‏مَا لَمْ يُضْمَنْ ‏","","",""],[2448,2448,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى عَبْدًا وَلَمْ يَشْتَرِطْ مَالَهُ فَلَا شَيْءَ لَهُ ‏","","",""],[2449,2449,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعَتَيْنِ وَعَنْ لِبْسَتَيْنِ عَنْ بَيْعِ ‏ ‏الْمُنَابَذَةِ ‏ ‏وَالْمُلَامَسَةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْمُنَابَذَةُ يَرْمِي هَذَا إِلَى ذَاكَ وَيَرْمِي ذَاكَ إِلَى ذَا قَالَ كَانَ هَذَا فِي الْجَاهِلِيَّةِ ‏","","",""],[2450,2450,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْغَرَرِ ‏ ‏وَعَنْ بَيْعِ ‏ ‏الْحَصَاةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏إِذَا رَمَى بِحَصًا وَجَبَ الْبَيْعُ ‏","","",""],[2451,2451,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏وَجَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ ‏ ‏نَسِيئَةً ‏ ‏ثُمَّ إِنَّ ‏ ‏الْحَسَنَ ‏ ‏نَسِيَ هَذَا الْحَدِيثَ وَلَمْ يَقُلْ ‏ ‏جَعْفَرٌ ‏ ‏ثُمَّ إِنَّ ‏ ‏الْحَسَنَ ‏ ‏نَسِيَ هَذَا الْحَدِيثَ ‏","","",""],[2452,2452,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قِرَاءَةً عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَسْلَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَكْرًا ‏ ‏فَجَاءَتْ إِبِلٌ مِنْ إِبِلِ الصَّدَقَةِ ‏ ‏قَالَ ‏ ‏أَبُو رَافِعٍ ‏ ‏فَأَمَرَنِي أَنْ أَقْضِيَ الرَّجُلَ ‏ ‏بَكْرَهُ ‏ ‏فَقُلْتُ لَمْ أَجِدْ فِي الْإِبِلِ إِلَّا جَمَلًا خِيَارًا ‏ ‏رَبَاعِيًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطِهِ إِيَّاهُ فَإِنَّ خَيْرَ النَّاسِ أَحْسَنُهُمْ قَضَاءً ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏هَذَا ‏ ‏يُقَوِّي قَوْلَ مَنْ يَقُولُ الْحَيَوَانُ بِالْحَيَوَانِ ‏","","",""],[2453,2453,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَلَقَّوْا الْجَلَبَ ‏ ‏مَنْ تَلَقَّاهُ فَاشْتَرَى مِنْهُ شَيْئًا فَهُوَ بِالْخِيَارِ إِذَا دَخَلَ السُّوقَ ‏","","",""],[2454,2454,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيعُ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا تَلَقَّوْا السِّلَعَ حَتَّى يُهْبَطَ بِهَا الْأَسْوَاقَ وَلَا ‏ ‏تَنَاجَشُوا ‏","","",""],[2455,2455,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ الْكَلْبِ ‏ ‏وَمَهْرِ الْبَغِيِّ ‏ ‏وَحُلْوَانِ ‏ ‏الْكَاهِنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حُلْوَانُ الْكَاهِنِ مَا يُعْطَى عَلَى كَهَانَتِهِ ‏","","",""],[2456,2456,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ الْآيَةُ فِي آخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي الرِّبَا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَلَاهُنَّ عَلَى النَّاسِ ثُمَّ ‏ ‏حَرَّمَ التِّجَارَةَ فِي الْخَمْرِ ‏","","",""],[2457,2457,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ الْآيَاتُ مِنْ أَوَاخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاقْتَرَأَهُنَّ عَلَى النَّاسِ ثُمَّ ‏ ‏نَهَى عَنْ التِّجَارَةِ فِي الْخَمْرِ ‏","","",""],[2458,2458,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ جُلُودِ الْمَيْتَةِ ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِبَاغُهَا طَهُورُهَا وَسَأَلْتُهُ عَنْ بَيْعِ الْخَمْرِ مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏فَقُلْتُ لَهُ إِنَّ لَنَا أَعْنَابًا وَإِنَّا نَتَّخِذُ مِنْهَا هَذِهِ الْخُمُورَ فَنَبِيعُهَا مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَهْدَى رَجُلٌ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏أَوْ ‏ ‏دَوْسٍ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاوِيَةً مِنْ خَمْرٍ فِي حَجَّةِ الْوَدَاعِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا عَلِمْتَ يَا أَبَا فُلَانٍ أَنَّ اللَّهَ قَدْ حَرَّمَهَا قَالَ لَا وَاللَّهِ قَالَ فَإِنَّ اللَّهَ قَدْ حَرَّمَهَا فَالْتَفَتَ إِلَى غُلَامِهِ فَقَالَ اخْرُجْ بِهَا إِلَى ‏ ‏الْحَزْوَرَةِ ‏ ‏فَبِعْهَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَ مَا عَلِمْتَ يَا أَبَا فُلَانٍ أَنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا قَالَ فَأَمَرَ بِهَا فَأُفْرِغَتْ فِي ‏ ‏الْبَطْحَاءِ ‏","","",""],[2459,2459,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْأَمْرُ عَلَى هَذَا لَا يُبَاعُ وَلَا يُوهَبُ ‏","","",""],[2460,2460,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏أَعْتَقَ رَجُلٌ مِنَّا عَبْدًا لَهُ عَنْ ‏ ‏دُبُرٍ ‏ ‏قَالَ فَدَعَا بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَاعَهُ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏وَإِنَّمَا مَاتَ عَامَ أَوَّلَ ‏","","",""],[2461,2461,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَلَدَتْ أَمَةُ الرَّجُلِ مِنْهُ فَهِيَ مُعْتَقَةٌ عَنْ ‏ ‏دُبُرٍ ‏ ‏مِنْهُ ‏ ‏أَوْ بَعْدَهُ ‏","","",""],[2462,2462,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُحَمَّدٍ الْحَنَفِيُّ الْمَدَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَهُمْ فِي مِكْيَالِهِمْ وَبَارِكْ لَهُمْ فِي ‏ ‏صَاعِهِمْ ‏ ‏وَمُدِّهِمْ ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏","","",""],[2463,2463,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏كَانَ عِنْدِي ‏ ‏مُدُّ ‏ ‏تَمْرٍ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُ أَطْيَبَ مِنْهُ ‏ ‏صَاعًا ‏ ‏بِصَاعَيْنِ ‏ ‏فَاشْتَرَيْتُ مِنْهُ فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مِنْ أَيْنَ لَكَ هَذَا يَا ‏ ‏بِلَالُ ‏ ‏قُلْتُ اشْتَرَيْتُ ‏ ‏صَاعًا ‏ ‏بِصَاعَيْنِ ‏ ‏قَالَ رُدَّهُ وَرُدَّ عَلَيْنَا تَمْرَنَا ‏","","",""],[2464,2464,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ هُوَ ابْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَجِيدِ بْنِ سُهَيْلِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏وَأَبَا هُرَيْرَةَ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ أَخَا ‏ ‏بَنِي عَدِيٍّ الْأَنْصَارِيَّ ‏ ‏فَاسْتَعْمَلَهُ عَلَى ‏ ‏خَيْبَرَ ‏ ‏فَقَدِمَ بِتَمْرٍ جَنِيبٍ ‏ ‏قَالَ ‏ ‏ابْنُ مَسْلَمَةَ ‏ ‏يَعْنِي جَيِّدًا ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكُلُّ تَمْرِ ‏ ‏خَيْبَرَ ‏ ‏هَكَذَا قَالَ لَا وَاللَّهِ يَا رَسُولَ اللَّهِ إِنَّا لَنَشْتَرِي ‏ ‏الصَّاعَ ‏ ‏بِالصَّاعَيْنِ ‏ ‏مِنْ ‏ ‏الْجَمْعِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَفْعَلُوا وَلَكِنْ مِثْلًا بِمِثْلٍ أَوْ بِيعُوا هَذَا وَاشْتَرُوا بِثَمَنِهِ مِنْ هَذَا وَكَذَلِكَ الْمِيزَانُ ‏","","",""],[2465,2465,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الذَّهَبُ بِالذَّهَبِ ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالْفِضَّةُ بِالْفِضَّةِ ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالتَّمْرُ بِالتَّمْرِ ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالْبُرُّ بِالْبُرِّ ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَالشَّعِيرُ بِالشَّعِيرِ ‏ ‏هَاءَ وَهَاءَ ‏ ‏وَلَا فَضْلَ بَيْنَهُمَا ‏","","",""],[2466,2466,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏قَالَ ‏ ‏قَامَ نَاسٌ فِي إِمَارَةِ ‏ ‏مُعَاوِيَةَ ‏ ‏يَبِيعُونَ آنِيَةَ الذَّهَبِ وَالْفِضَّةِ إِلَى الْعَطَاءِ فَقَامَ ‏ ‏عُبَادَةُ بْنُ الصَّامِتِ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الذَّهَبِ بِالذَّهَبِ وَالْفِضَّةِ بِالْفِضَّةِ وَالْبُرِّ بِالْبُرِّ وَالتَّمْرِ بِالتَّمْرِ وَالشَّعِيرِ بِالشَّعِيرِ وَالْمِلْحِ بِالْمِلْحِ إِلَّا مِثْلًا بِمِثْلٍ سَوَاءً بِسَوَاءٍ فَمَنْ زَادَ أَوْ ازْدَادَ فَقَدْ أَرْبَى ‏","","",""],[2467,2467,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الرِّبَا فِي الدَّيْنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏مَعْنَاهُ دِرْهَمٌ بِدِرْهَمَيْنِ ‏","","",""],[2468,2468,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ الدَّرَاهِمَ وَأَبِيعُ بِالدَّرَاهِمِ وَآخُذُ الدَّنَانِيرَ ‏ ‏وَرُبَّمَا قَالَ أَقْبِضُ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ رُوَيْدَكَ أَسْأَلُكَ إِنِّي أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ الدَّرَاهِمَ وَأَبِيعُ بِالدَّرَاهِمِ وَآخُذُ الدَّنَانِيرَ قَالَ ‏ ‏لَا بَأْسَ أَنْ تَأْخُذَ بِسِعْرِ يَوْمِكَ مَا لَمْ تَفْتَرِقَا وَبَيْنَكُمَا شَيْءٌ ‏","","",""],[2469,2469,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ دِرْعَهُ لَمَرْهُونَةٌ عِنْدَ رَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏بِثَلَاثِينَ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ ‏","","",""],[2470,2470,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَهُمْ ‏ ‏يُسْلِفُونَ ‏ ‏فِي الثِّمَارِ فِي سَنَتَيْنِ وَثَلَاثٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلِّفُوا ‏ ‏فِي الثِّمَارِ فِي كَيْلٍ مَعْلُومٍ وَوَزْنٍ مَعْلُومٍ ‏ ‏وَقَدْ كَانَ ‏ ‏سُفْيَانُ ‏ ‏يَذْكُرُهُ زَمَانًا إِلَى أَجَلٍ مَعْلُومٍ ثُمَّ شَكَّكَهُ ‏ ‏عَبَّادُ بْنُ كَثِيرٍ ‏","","",""],[2471,2471,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزَنَ لَهُمْ دَرَاهِمَ فَأَرْجَحَهَا ‏","","",""],[2472,2472,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏جَلَبْتُ أَنَا ‏ ‏وَمَخْرَمَةُ الْعَبْدِيُّ ‏ ‏بَزًّا ‏ ‏مِنْ ‏ ‏الْبَحْرَيْنِ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي فَسَاوَمَنَا بِسَرَاوِيلَ ‏ ‏أَوْ اشْتَرَى مِنَّا سَرَاوِيلَ ‏ ‏وَثَمَّ وَزَّانٌ يَزِنُ بِالْأَجْرِ فَقَالَ لِلْوَزَّانِ ‏ ‏زِنْ وَأَرْجِحْ فَلَمَّا ذَهَبَ يَمْشِي قَالُوا هَذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2473,2473,"","","‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَإِذَا أُتْبِعَ أَحَدُكُمْ عَلَى ‏ ‏مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[2474,2474,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ تَقَاضَى ‏ ‏ابْنَ أَبِي حَدْرَدٍ ‏ ‏دَيْنًا كَانَ لَهُ عَلَيْهِ فِي الْمَسْجِدِ فَارْتَفَعَتْ أَصْوَاتُهُمَا حَتَّى سَمِعَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي بَيْتِهِ فَخَرَجَ إِلَيْهِمَا فَنَادَى يَا ‏ ‏كَعْبُ ‏ ‏قَالَ لَبَّيْكَ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏ضَعْ مِنْ دَيْنِكَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ أَيْ الشَّطْرَ قَالَ قَدْ فَعَلْتُ قَالَ قُمْ فَاقْضِهِ ‏","","",""],[2475,2475,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي الْيَسَرِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏أَنْظَرَ ‏ ‏مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ قَالَ فَبَزَقَ فِي صَحِيفَتِهِ فَقَالَ اذْهَبْ فَهِيَ لَكَ لِغَرِيمِهِ وَذَكَرَ أَنَّهُ كَانَ مُعْسِرًا ‏","","",""],[2476,2476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَفَّسَ عَنْ غَرِيمِهِ أَوْ مَحَا عَنْهُ كَانَ فِي ظِلِّ الْعَرْشِ يَوْمَ الْقِيَامَةِ ‏","","",""],[2477,2477,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرِ بْنَ مُحَمَّدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَ مَالَهُ بِعَيْنِهِ عِنْدَ إِنْسَانٍ قَدْ أَفْلَسَ ‏ ‏أَوْ عِنْدَ رَجُلٍ قَدْ أَفْلَسَ ‏ ‏فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ ‏","","",""],[2478,2478,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسُ الْمُؤْمِنِ مُعَلَّقَةٌ مَا كَانَ عَلَيْهِ دَيْنٌ ‏","","",""],[2479,2479,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ مِنْ الْكِبْرِ ‏ ‏وَالْغُلُولِ ‏ ‏وَالدَّيْنِ ‏","","",""],[2480,2480,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏وَأَبُو الْوَلِيدِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ لِيُصَلِّيَ عَلَيْهِ فَقَالَ ‏ ‏صَلُّوا عَلَى صَاحِبِكُمْ فَإِنَّ عَلَيْهِ دَيْنًا قَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏هُوَ عَلَيَّ يَا رَسُولَ اللَّهِ قَالَ بِالْوَفَاءِ قَالَ بِالْوَفَاءِ قَالَ فَصَلَّى عَلَيْهِ ‏","","",""],[2481,2481,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا عَلَى الْأَرْضِ مُؤْمِنٌ إِلَّا أَنَا أَوْلَى النَّاسِ بِهِ فَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَلْأُدْعَ لَهُ فَأَنَا مَوْلَاهُ وَمَنْ تَرَكَ مَالًا ‏ ‏فَلِعَصَبَتِهِ ‏ ‏مَنْ كَانَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏ضَيَاعًا ‏ ‏يَعْنِي عِيَالًا وَقَالَ فَلْأُدْعَ لَهُ ‏ ‏يَعْنِي ادْعُونِي لَهُ أَقْضِ عَنْهُ ‏","","",""],[2482,2482,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ الْحِزَامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏الْأَسْلَمِيِّينَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ مَعَ الدَّائِنِ حَتَّى ‏ ‏يُقْضَى دَيْنُهُ مَا لَمْ يَكُنْ فِيمَا يَكْرَهُ اللَّهُ قَالَ وَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏يَقُولُ لِخَازِنِهِ اذْهَبْ فَخُذْ لِي بِدَيْنٍ فَإِنِّي أَكْرَهُ أَنْ أَبِيتَ لَيْلَةً إِلَّا وَاللَّهُ مَعِي بَعْدَمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2483,2483,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْيَدِ مَا أَخَذَتْ حَتَّى تُؤَدِّيَهُ ‏","","",""],[2484,2484,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏طَلْقُ بْنُ غَنَّامٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏وَقَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَدِّ إِلَى مَنْ ائْتَمَنَكَ وَلَا تَخُنْ مَنْ خَانَكَ ‏","","",""],[2485,2485,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى بَعْضُ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ ‏ ‏قَصْعَةً ‏ ‏فِيهَا ‏ ‏ثَرِيدٌ ‏ ‏وَهُوَ فِي بَيْتِ بَعْضِ أَزْوَاجِهِ فَضَرَبَتْ ‏ ‏الْقَصْعَةَ ‏ ‏فَانْكَسَرَتْ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْخُذُ ‏ ‏الثَّرِيدَ ‏ ‏فَيَرُدُّهُ فِي ‏ ‏الصَّحْفَةِ ‏ ‏وَهُوَ يَقُولُ ‏ ‏كُلُوا غَارَتْ أُمُّكُمْ ثُمَّ انْتَظَرَ حَتَّى جَاءَتْ ‏ ‏قَصْعَةٌ ‏ ‏صَحِيحَةٌ فَأَخَذَهَا فَأَعْطَاهَا صَاحِبَةَ ‏ ‏الْقَصْعَةِ ‏ ‏الْمَكْسُورَةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏نَقُولُ بِهَذَا ‏","","",""],[2486,2486,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏وَعَاصِمٍ ‏ ‏ابْنَيْ ‏ ‏سُفْيَانَ بْنِ عَبْدِ اللَّهِ بْنِ رَبِيعَةَ الثَّقَفِيِّ ‏ ‏أَنَّ ‏ ‏سُفْيَانَ بْنَ عَبْدِ اللَّهِ ‏ ‏وَجَدَ ‏ ‏عَيْبَةً ‏ ‏فَأَتَى بِهَا ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏عَرِّفْهَا سَنَةً فَإِنْ عُرِفَتْ فَذَاكَ وَإِلَّا فَهِيَ لَكَ فَلَمْ تُعْرَفْ فَلَقِيَهُ بِهَا فِي الْعَامِ الْمُقْبِلِ فِي الْمَوْسِمِ فَذَكَرَهَا لَهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏هِيَ لَكَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا بِذَلِكَ قَالَ لَا حَاجَةَ لِي بِهَا فَقَبَضَهَا ‏ ‏عُمَرُ ‏ ‏فَجَعَلَهَا فِي بَيْتِ الْمَالِ ‏","","",""],[2487,2487,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُعَاذُ بْنُ هَانِئٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ عَامَ فُتِحَتْ ‏ ‏مَكَّةُ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ حَبَسَ عَنْ ‏ ‏مَكَّةَ ‏ ‏الْفِيلَ وَسَلَّطَ عَلَيْهِمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُؤْمِنِينَ أَلَا وَإِنَّهَا لَمْ تَحِلَّ لِأَحَدٍ قَبْلِي وَلَا تَحِلُّ لِأَحَدٍ بَعْدِي أَلَا وَإِنَّهَا سَاعَتِي هَذِهِ حَرَامٌ لَا ‏ ‏يُخْتَلَى ‏ ‏خَلَاهَا ‏ ‏وَلَا ‏ ‏يُعْضَدُ ‏ ‏شَجَرُهَا وَلَا تُلْتَقَطُ ‏ ‏سَاقِطَتُهَا ‏ ‏إِلَّا ‏ ‏لِمُنْشِدٍ ‏","","",""],[2488,2488,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِي مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْجَارُودِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَالَّةُ ‏ ‏الْمُسْلِمِ حَرَقُ النَّارِ ‏","","",""],[2489,2489,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِي مُسْلِمٍ الْجَذْمِيِّ ‏ ‏عَنْ ‏ ‏الْجَارُودِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَالَّةُ ‏ ‏الْمُسْلِمِ حَرَقُ النَّارِ ‏ ‏ضَالَّةُ ‏ ‏الْمُسْلِمِ حَرَقُ النَّارِ ‏ ‏ضَالَّةُ ‏ ‏الْمُسْلِمِ حَرَقُ النَّارِ لَا تَقْرَبَنَّهَا قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏اللُّقَطَةُ ‏ ‏نَجِدُهَا قَالَ ‏ ‏أَنْشِدْهَا ‏ ‏وَلَا تَكْتُمْ وَلَا تُغَيِّبْ فَإِنْ جَاءَ رَبُّهَا فَادْفَعْهَا إِلَيْهِ وَإِلَّا فَمَالُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ ‏","","",""],[2490,2490,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ يَعْقُوبَ الْكُوفِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السَّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ قَضِيبٌ مِنْ أَرَاكٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَخَاهُ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا أُمَامَةَ الْحَارِثِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏نَحْوَهُ ‏","","",""],[2491,2491,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏خَرَشَةَ بْنِ الْحُرِّ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ وَلَا يَنْظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ فَقُلْتُ يَا رَسُولَ اللَّهِ مَنْ هُمْ خَابُوا وَخَسِرُوا فَأَعَادَهَا فَقُلْتُ مَنْ هُمْ يَا رَسُولَ اللَّهِ فَقَالَ الْمُسْبِلُ وَالْمَنَّانُ وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ كَاذِبًا ‏","","",""],[2492,2492,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏شُعَيْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏طَلْحَةُ بْنُ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ سَهْلٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ظَلَمَ مِنْ الْأَرْضِ شِبْرًا فَإِنَّهُ يُطَوَّقُهُ مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[2493,2493,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ رَافِعٍ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْيَا أَرْضًا ‏ ‏مَيْتَةً ‏ ‏فَلَهُ فِيهَا أَجْرٌ وَمَا أَكَلَتْ الْعَافِيَةُ مِنْهَا فَلَهُ فِيهَا صَدَقَةٌ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏الْعَافِيَةُ الطَّيْرُ وَغَيْرُ ذَلِكَ ‏","","",""],[2494,2494,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ الْحُمَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ سَعِيدِ بْنِ عَلْقَمَةَ بْنِ سَعِيدِ بْنِ أَبْيَضَ بْنِ حَمَّالٍ السَّبَائِيُّ الْمَأْرِبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏ثَابِتُ بْنُ سَعِيدِ بْنِ أَبْيَضَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏سَعِيدَ بْنَ أَبْيَضَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبْيَضَ بْنِ حَمَّالٍ ‏ ‏أَنَّهُ ‏ ‏اسْتَقْطَعَ ‏ ‏الْمِلْحَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي يُقَالُ لَهُ مِلْحُ ‏ ‏شَذَّا ‏ ‏بِمَأْرِبَ ‏ ‏فَأَقْطَعَهُ ‏ ‏ثُمَّ إِنَّ ‏ ‏الْأَقْرَعَ بْنَ حَابِسٍ التَّمِيمِيَّ ‏ ‏قَالَ يَا نَبِيَّ اللَّهِ إِنِّي قَدْ وَرَدْتُ الْمِلْحَ فِي الْجَاهِلِيَّةِ وَهُوَ بِأَرْضٍ لَيْسَ بِهَا مَاءٌ وَمَنْ وَرَدَهُ أَخَذَهُ وَهُوَ مِثْلُ مَاءِ الْعِدِّ ‏ ‏فَاسْتَقَالَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَبْيَضَ فِي ‏ ‏قَطِيعَتِهِ ‏ ‏فِي الْمِلْحِ فَقُلْتُ قَدْ ‏ ‏أَقَلْتُهُ ‏ ‏عَلَى أَنْ تَجْعَلَهُ مِنِّي صَدَقَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ مِنْكَ صَدَقَةٌ وَهُوَ مِثْلُ مَاءِ الْعِدِّ مَنْ وَرَدَهُ أَخَذَهُ قَالَ ‏ ‏وَقَطَعَ ‏ ‏لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضًا وَكَذَا ‏ ‏بِالْجَوْفِ ‏ ‏جَوْفِ مُرَادٍ ‏ ‏مَكَانَهُ حِينَ ‏ ‏أَقَالَهُ ‏ ‏مِنْهُ قَالَ ‏ ‏الْفَرَجُ ‏ ‏فَهُوَ عَلَى ذَلِكَ مَنْ وَرَدَهُ أَخَذَهُ ‏","","",""],[2495,2495,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْطَعَهُ ‏ ‏أَرْضًا قَالَ فَأَرْسَلَ مَعِي ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ أَعْطِهَا إِيَّاهُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏بِهَذَا الْحَدِيثِ ‏","","",""],[2496,2496,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏أُمُّ مُبَشِّرٍ ‏ ‏امْرَأَةُ ‏ ‏زَيْدِ بْنِ حَارِثَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَائِطٍ لِي فَقَالَ يَا ‏ ‏أُمَّ مُبَشِّرٍ ‏ ‏أَمُسْلِمٌ غَرَسَ هَذَا أَمْ كَافِرٌ قُلْتُ مُسْلِمٌ فَقَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا فَيَأْكُلُ مِنْهُ إِنْسَانٌ أَوْ دَابَّةٌ أَوْ طَيْرٌ إِلَّا كَانَتْ لَهُ صَدَقَةٌ ‏","","",""],[2497,2497,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمِّي ‏ ‏ثَابِتُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَبْيَضَ بْنِ حَمَّالٍ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏حِمَى ‏ ‏الْأَرَاكِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏فِي ‏ ‏الْأَرَاكِ ‏ ‏فَقَالَ أَرَاكَةٌ فِي حِظَارِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏فِي ‏ ‏الْأَرَاكِ ‏ ‏قَالَ ‏ ‏فَرَجٌ ‏ ‏يَعْنِي ‏ ‏أَبْيَضُ ‏ ‏بِحِظَارِي الْأَرْضَ الَّتِي فِيهَا الزَّرْعُ الْمُحَاطُ عَلَيْهَا ‏","","",""],[2498,2498,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِيَاسَ بْنَ عَبْدٍ الْمُزَنِيَّ ‏ ‏وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الْمَاءَ فَإِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ بَيْعِ الْمَاءِ ‏ ‏وَقَالَ ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏لَا نَدْرِي أَيَّ مَاءٍ قَالَ يَقُولُ لَا أَدْرِي مَاءً جَارِيًا أَوْ الْمَاءَ الْمُسْتَقَى ‏","","",""],[2499,2499,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏فَزَارَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُهَيْسَةَ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنَهُ فَدَخَلَ بَيْنَهُ وَبَيْنَ قَمِيصِهِ ‏ ‏وَقَدْ قَالَ ‏ ‏عُثْمَانُ ‏ ‏فَالْتَزَمَهُ ‏ ‏فَقَالَ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ فَقَالَ ‏ ‏الْمِلْحُ وَالْمَاءُ قَالَ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ إِنْ تَفْعَلْ الْخَيْرَ خَيْرٌ لَكَ قَالَ مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ قَالَ إِنْ تَفْعَلْ الْخَيْرَ خَيْرٌ لَكَ وَانْتَهَى إِلَى الْمِلْحِ وَالْمَاءِ ‏ ‏قِيلَ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهِ فَأَوْمَأَ بِرَأْسِهِ ‏","","",""],[2500,2500,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَلَ ‏ ‏خَيْبَرَ ‏ ‏بِشَطْرِ مَا يَخْرُجُ مِنْهَا مِنْ ثَمَرَةٍ أَوْ زَرْعٍ ‏","","",""],[2501,2501,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْحَسَنِ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا بْنِ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏كُنَّا ‏ ‏نُخَابِرُ ‏ ‏قَبْلَ أَنْ ‏ ‏يَنْهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْخِبْرِ ‏ ‏بَسَنَتَيْنِ أَوْ ثَلَاثٍ عَلَى الثُّلُثِ وَالشَّطْرِ وَشَيْءٍ مِنْ تِبْنٍ فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَحْرُثْهَا فَإِنْ كَرِهَ أَنْ يَحْرُثَهَا فَلْيَمْنَحْهَا أَخَاهُ فَإِنْ كَرِهَ أَنْ يَمْنَحَهَا أَخَاهُ فَلْيَدَعْهَا ‏","","",""],[2502,2502,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْقِلٍ ‏ ‏عَنْ الْمُزَارَعَةِ ‏ ‏فَقَالَ أَخْبَرَنِي ‏ ‏ثَابِتُ بْنُ الضَّحَّاكِ الْأَنْصَارِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَارَعَةِ ‏ ‏قَالَ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏لَا أَقُولُ بِالْأَوَّلِ ‏","","",""],[2503,2503,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْأَرْضِ ‏ ‏الْبَيْضَاءِ ‏ ‏سَنَتَيْنِ أَوْ ثَلَاثًا ‏","","",""],[2504,2504,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عِكْرِمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَبِيبَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُكْرِي ‏ ‏الْأَرْضَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا عَلَى ‏ ‏السَّوَاقِي ‏ ‏مِنْ الزَّرْعِ وَبِمَا ‏ ‏سَعِدَ ‏ ‏مِنْ الْمَاءِ مِنْهَا فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ وَأَذِنَ لَنَا ‏ ‏أَوْ قَالَ رَخَّصَ لَنَا ‏ ‏فِي أَنْ ‏ ‏نُكْرِيَهَا ‏ ‏بِالذَّهَبِ وَالْوَرِقِ ‏","","",""],[2505,2505,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَسْعُودِ بْنِ نِيَارٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏سَهْلُ بْنُ أَبِي حَثْمَةَ ‏ ‏إِلَى مَجْلِسِنَا ‏ ‏فَحَدَّثَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏خَرَصْتُمْ ‏ ‏فَخُذُوا وَدَعُوا دَعُوا الثُّلُثَ فَإِنْ لَمْ تَدَعُوا الثُّلُثَ فَدَعُوا الرُّبُعَ ‏","","",""],[2506,2506,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ الْإِمَاءِ ‏","","",""],[2507,2507,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏أَنَّ ‏ ‏السَّائِبَ بْنَ يَزِيدَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏رَافِعَ بْنَ خَدِيجٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَسْبُ ‏ ‏الْحَجَّامِ ‏ ‏خَبِيثٌ ‏ ‏وَمَهْرُ الْبَغِيِّ ‏ ‏خَبِيثٌ وَثَمَنُ الْكَلْبِ خَبِيثٌ ‏","","",""],[2508,2508,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَمَهُ ‏ ‏أَبُو طَيْبَةَ ‏ ‏وَأَمَرَ لَهُ بِصَاعَيْنِ مِنْ طَعَامٍ ‏","","",""],[2509,2509,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ ‏ ‏عَسْبِ ‏ ‏الْفَحْلِ ‏","","",""],[2510,2510,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الْمَهْرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَسْبِ ‏ ‏الْفَحْلِ ‏ ‏وَأَجْرِ الْمُومِسَةِ ‏","","",""],[2511,2511,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ هُوَ ابْنُ إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْمَلِكِ بْنَ عُمَيْرٍ ‏ ‏يُحَدِّثُ قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏سَعِيدِ بْنِ حُرَيْثٍ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَاعَ مِنْكُمْ دَارًا أَوْ عَقَارًا ‏ ‏قَمِنٌ ‏ ‏أَنْ لَا يُبَارَكَ لَهُ إِلَّا أَنْ يَجْعَلَهُ فِي مِثْلِهِ ‏","","",""],[2512,2512,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عَرْعَرَةُ بْنُ الْبِرِنْدِ السَّامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ احْتَفَرَ بِئْرًا فَلَيْسَ لِأَحَدٍ أَنْ يَحْفِرَ حَوْلَهُ أَرْبَعِينَ ذِرَاعًا ‏ ‏عَطَنًا ‏ ‏لِمَاشِيَتِهِ ‏","","",""],[2513,2513,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الشُّفْعَةِ ‏ ‏إِذَا كَانَ طَرِيقُهُمَا وَاحِدًا قَالَ ‏ ‏يُنْظَرُ بِهَا وَإِنْ كَانَ صَاحِبُهَا غَائِبًا ‏","","",""],[2514,2514,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالشُّفْعَةِ ‏ ‏فِي كُلِّ شِرْكٍ لَمْ يُقْسَمْ ‏ ‏رَبْعَةٍ ‏ ‏أَوْ ‏ ‏حَائِطٍ ‏ ‏لَا يَحِلُّ لَهُ أَنْ يَبِيعَ حَتَّى يُؤْذِنَ شَرِيكَهُ فَإِنْ شَاءَ أَخَذَ وَإِنْ شَاءَ تَرَكَ فَإِنْ بَاعَ وَلَمْ يُؤْذِنْهُ فَهُوَ أَحَقُّ بِهِ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[2515,2515,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏اسْتَأْذَنَ عَلَى ‏ ‏عُمَرَ ‏ ‏ثَلَاثَ مَرَّاتٍ فَلَمْ يُؤْذَنْ لَهُ فَرَجَعَ فَقَالَ مَا رَجَعَكَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اسْتَأْذَنَ الْمُسْتَأْذِنُ ثَلَاثَ مَرَّاتٍ فَإِنْ أُذِنَ لَهُ وَإِلَّا فَلْيَرْجِعْ فَقَالَ لَتَأْتِيَنَّ بِمَنْ يَشْهَدُ مَعَكَ أَوْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَأَتَانَا وَأَنَا فِي قَوْمٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ وَهُوَ فَزِعٌ مِنْ وَعِيدِ ‏ ‏عُمَرَ ‏ ‏إِيَّاهُ فَقَامَ عَلَيْنَا فَقَالَ أَنْشُدُ اللَّهَ مِنْكُمْ رَجُلًا سَمِعَ ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا شَهِدَ لِي بِهِ قَالَ فَرَفَعْتُ رَأْسِي فَقُلْتُ أَخْبِرْهُ أَنِّي مَعَكَ عَلَى هَذَا وَقَالَ ذَاكَ آخَرُونَ فَسُرِّيَ عَنْ ‏ ‏أَبِي مُوسَى ‏","","",""],[2516,2516,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَرَبْتُ بَابَهُ فَقَالَ ‏ ‏مَنْ ذَا فَقُلْتُ أَنَا قَالَ أَنَا أَنَا فَكَرِهَ ذَاكَ ‏","","",""],[2517,2517,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَارِبَ بْنَ دِثَارٍ ‏ ‏يَذْكُرُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَطْرُقَ ‏ ‏الرَّجُلُ أَهْلَهُ لَيْلًا أَوْ يُخَوِّنَهُمْ أَوْ يَلْتَمِسَ عَثَرَاتِهِمْ قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَوْلُهُ أَوْ يُخَوِّنَهُمْ أَوْ يَلْتَمِسَ عَثَرَاتِهِمْ مَا أَدْرِي شَيْءٌ قَالَهُ ‏ ‏مُحَارِبٌ ‏ ‏أَوْ شَيْءٌ هُوَ فِي الْحَدِيثِ ‏","","",""],[2518,2518,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏اسْتَشْرَفَهُ ‏ ‏النَّاسُ فَقَالُوا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَخَرَجْتُ فِيمَنْ خَرَجَ فَلَمَّا رَأَيْتُ وَجْهَهُ عَرَفْتُ أَنَّ وَجْهَهُ لَيْسَ بِوَجْهِ كَذَّابٍ فَكَانَ أَوَّلَ مَا سَمِعْتُهُ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏أَفْشُوا السَّلَامَ وَأَطْعِمُوا الطَّعَامَ ‏ ‏وَصِلُوا ‏ ‏الْأَرْحَامَ ‏ ‏وَصَلُّوا وَالنَّاسُ نِيَامٌ تَدْخُلُوا الْجَنَّةَ بِسَلَامٍ ‏","","",""],[2519,2519,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ يُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ وَيُشَمِّتُهُ إِذَا عَطَسَ وَيَعُودُهُ إِذَا مَرِضَ وَيُجِيبُهُ إِذَا دَعَاهُ وَيَشْهَدُهُ إِذَا تُوُفِّيَ وَيُحِبُّ لَهُ مَا يُحِبُّ لِنَفْسِهِ وَيَنْصَحُ لَهُ بِالْغَيْبِ ‏","","",""],[2520,2520,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو هَانِىءٍ الْخَوْلَانِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ الْجَنْبِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْقَائِمُ عَلَى الْقَاعِدِ وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏","","",""],[2521,2521,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏إِذَا سَلَّمَ أَحَدُهُمْ فَإِنَّمَا يَقُولُ ‏ ‏السَّامُ عَلَيْكَ قُلْ عَلَيْكَ ‏","","",""],[2522,2522,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ ‏ ‏وَحَدَّثَ ‏ ‏ثَابِتٌ ‏ ‏أَنَّهُ كَانَ مَعَ ‏ ‏أَنَسٍ ‏ ‏فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ ‏ ‏وَحَدَّثَ ‏ ‏أَنَسٌ ‏ ‏أَنَّهُ كَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ ‏","","",""],[2523,2523,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي حُسَيْنٍ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ ‏ ‏إِحْدَى نِسَاءِ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏أَنَّهَا ‏ ‏بَيْنَا هِيَ فِي نِسْوَةٍ مَرَّ عَلَيْهِنَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ عَلَيْهِنَّ ‏","","",""],[2524,2524,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشُ ‏ ‏هَذَا ‏ ‏جِبْرِيلُ ‏ ‏يَقْرَأُ عَلَيْكِ السَّلَامَ قَالَتْ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ قَالَتْ وَهُوَ يَرَى مَا لَا ‏ ‏أَرَى ‏","","",""],[2525,2525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ هُوَ ابْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ حِينَ قَضَى صَلَاتَهُ فَكُنْتُ أَوَّلَ مَنْ حَيَّا بِتَحِيَّةِ الْإِسْلَامِ قَالَ ‏ ‏عَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ مِمَّنْ أَنْتَ قَالَ قُلْتُ مِنْ ‏ ‏غِفَارٍ ‏ ‏قَالَ فَأَهْوَى بِيَدِهِ قُلْتُ فِي نَفْسِي كَرِهَ أَنِّي انْتَمَيْتُ إِلَى ‏ ‏غِفَارٍ ‏","","",""],[2526,2526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ السَّلَامُ عَلَيْكُمْ فَرَدَّ عَلَيْهِ وَقَالَ ‏ ‏عَشْرٌ ثُمَّ جَاءَ رَجُلٌ فَسَلَّمَ فَقَالَ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ فَرَدَّ عَلَيْهِ وَقَالَ عِشْرُونَ ثُمَّ جَاءَ رَجُلٌ فَسَلَّمَ فَقَالَ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ فَرَدَّ عَلَيْهِ وَقَالَ ثَلَاثُونَ ‏","","",""],[2527,2527,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏الْحُضَيْنِ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ بْنِ قُنْفُذٍ ‏ ‏أَنَّهُ ‏ ‏سَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَبُولُ فَلَمْ يَرُدَّ عَلَيْهِ السَّلَامَ حَتَّى تَوَضَّأَ فَلَمَّا تَوَضَّأَ رَدَّهُ عَلَيْهِ ‏","","",""],[2528,2528,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ بِسْطَامَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا عَلَى النِّسَاءِ قِيلَ يَا رَسُولَ اللَّهِ إِلَّا الْحَمْوُ قَالَ الْحَمْوُ الْمَوْتُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏الْحَمْوُ ‏ ‏يَعْنِي قَرَابَةَ الزَّوْجِ ‏","","",""],[2529,2529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَظْرَةِ الْفَجْأَةِ فَقَالَ ‏ ‏اصْرِفْ بَصَرَكَ ‏","","",""],[2530,2530,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏ذَيْلِ ‏ ‏الْمَرْأَةِ فَقَالَ ‏ ‏شِبْرًا فَقُلْتُ يَا رَسُولَ اللَّهِ إِذَنْ تَبْدُوَ أَقْدَامُهُنَّ قَالَ قَدْرَ ذِرَاعٍ لَا يَزِدْنَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏النَّاسُ يَقُولُونَ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏","","",""],[2531,2531,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏حَدَّثَنِي ‏ ‏رِبْعِيُّ بْنُ حِرَاشٍ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏أُخْتٍ لِحُذَيْفَةَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ أَمَا لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ بِهِ أَمَا إِنَّهُ لَيْسَتْ مِنْكُنَّ امْرَأَةٌ تَحَلَّى الذَّهَبَ فَتُظْهِرَهُ إِلَّا عُذِّبَتْ بِهِ ‏","","",""],[2532,2532,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَيُّمَا امْرَأَةٍ اسْتَعْطَرَتْ ثُمَّ خَرَجَتْ لِيُوجَدَ رِيحُهَا فَهِيَ زَانِيَةٌ وَكُلُّ عَيْنٍ زَانٍ ‏ ‏وَقَالَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏يَرْفَعُهُ بَعْضُ أَصْحَابِنَا ‏","","",""],[2533,2533,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاشِمَاتِ ‏ ‏وَالْمُسْتَوْشِمَاتِ ‏ ‏وَالْمُتَنَمِّصَاتِ ‏ ‏وَالْمُتَفَلِّجَاتِ ‏ ‏لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏يُقَالُ لَهَا ‏ ‏أُمُّ يَعْقُوبَ ‏ ‏فَجَاءَتْ فَقَالَتْ بَلَغَنِي أَنَّكَ لَعَنْتَ ‏ ‏كَيْتَ ‏ ‏وَكَيْتَ فَقَالَ وَمَا لِي لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي كِتَابِ اللَّهِ فَقَالَتْ لَقَدْ قَرَأْتُ مَا بَيْنَ اللَّوْحَيْنِ فَمَا وَجَدْتُ فِيهِ مَا تَقُولُ قَالَ لَئِنْ كُنْتِ ‏ ‏قَرَأْتِيهِ لَقَدْ ‏ ‏وَجَدْتِيهِ أَمَا قَرَأْتِ ‏ { ‏مَا آتَاكُمْ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا ‏} ‏فَقَالَتْ بَلَى قَالَ فَإِنَّهُ قَدْ نَهَى عَنْهُ فَقَالَتْ فَإِنِّي ‏ ‏أَرَى أَهْلَكَ يَفْعَلُونَهُ قَالَ فَادْخُلِي فَانْظُرِي فَدَخَلَتْ فَنَظَرَتْ فَلَمْ تَرَ مِنْ حَاجَتِهَا شَيْئًا فَقَالَ لَوْ كَانَتْ كَذَلِكِ مَا جَامَعْتُهَا ‏","","",""],[2534,2534,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ الْحَضْرَمِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ الْحِمْيَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْحُصَيْنِ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ عَشْرِ خِصَالٍ ‏ ‏مُكَامَعَةِ ‏ ‏الرَّجُلِ الرَّجُلَ فِي ‏ ‏شِعَارٍ ‏ ‏وَاحِدٍ لَيْسَ بَيْنَهُمَا شَيْءٌ ‏ ‏وَمُكَامَعَةِ ‏ ‏الْمَرْأَةِ الْمَرْأَةَ فِي ‏ ‏شِعَارٍ ‏ ‏وَاحِدٍ لَيْسَ بَيْنَهُمَا شَيْءٌ وَالنَّتْفِ ‏ ‏وَالْوَشْمِ ‏ ‏وَالنُّهْبَةِ ‏ ‏وَرُكُوبِ النُّمُورِ ‏ ‏وَاتِّخَاذِ ‏ ‏الدِّيبَاجِ ‏ ‏هَا هُنَا عَلَى الْعَاتِقَيْنِ وَفِي أَسْفَلِ الثِّيَابِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَبُو عَامِرٍ ‏ ‏شَيْخٌ لَهُمْ وَالْمُكَامَعَةُ الْمُضَاجَعَةُ ‏","","",""],[2535,2535,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَوَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ هُوَ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ وَالْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ وَقَالَ ‏ ‏أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ قَالَ فَأَخْرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُلَانًا وَأَخْرَجَ ‏ ‏عُمَرُ ‏ ‏فُلَانًا ‏ ‏أَوْ فُلَانَةً ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏فَأَشُكُّ ‏","","",""],[2536,2536,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏زُرْعَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏قَالَ ‏ ‏جَلَسَ عِنْدَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفَخِذِي مُنْكَشِفَةٌ فَقَالَ ‏ ‏خَمِّرْ ‏ ‏عَلَيْكَ أَمَا عَلِمْتَ أَنَّ الْفَخِذَ عَوْرَةٌ ‏","","",""],[2537,2537,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏نِسْوَةٌ مِنْ أَهْلِ ‏ ‏حِمْصَ ‏ ‏يَسْتَفْتِينَهَا فَقَالَتْ لَعَلَّكُنَّ مِنْ النِّسْوَةِ اللَّاتِي يَدْخُلْنَ الْحَمَّامَاتِ قُلْنَ نَعَمْ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ امْرَأَةٍ تَضَعُ ثِيَابَهَا فِي غَيْرِ بَيْتِ زَوْجِهَا إِلَّا هَتَكَتْ مَا بَيْنَهَا وَبَيْنَ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏هَذَا الْحَدِيثَ ‏","","",""],[2538,2538,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِيمُ الرَّجُلُ ‏ ‏يَعْنِي أَخَاهُ ‏ ‏مِنْ مَجْلِسِهِ ثُمَّ يَقْعُدُ فِيهِ وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا ‏","","",""],[2539,2539,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ ‏ ‏أَوْ الرَّجُلُ ‏ ‏مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[2540,2540,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِنَاسٍ جُلُوسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏إِنْ كُنْتُمْ لَا بُدَّ فَاعِلِينَ فَاهْدُوا السَّبِيلَ وَأَفْشُوا السَّلَامَ وَأَعِينُوا الْمَظْلُومَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَسْمَعْ هَذَا الْحَدِيثَ ‏ ‏أَبُو إِسْحَقَ ‏ ‏مِنْ ‏ ‏الْبَرَاءِ ‏","","",""],[2541,2541,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ بْنِ أَبِي خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْتَلْقِيًا فِي الْمَسْجِدِ وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏","","",""],[2542,2542,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يُحْزِنُهُ ‏","","",""],[2543,2543,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏رُفَيْعٍ أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ ‏ ‏بِأَخَرَةٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ فِي الْمَجْلِسِ فَأَرَادَ أَنْ يَقُومَ قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ لَتَقُولُ الْآنَ كَلَامًا مَا كُنْتَ تَقُولُهُ فِيمَا خَلَا فَقَالَ هَذَا كَفَّارَةٌ لِمَا يَكُونُ فِي الْمَجَالِسِ ‏","","",""],[2544,2544,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عِيسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَاطِسُ يَقُولُ الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ وَيَقُولُ الَّذِي يُشَمِّتُهُ يَرْحَمُكُمْ اللَّهُ وَيَرُدُّ عَلَيْهِ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[2545,2545,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏عَطَسَ رَجُلَانِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَمَّتَ ‏ ‏أَوْ ‏ ‏سَمَّتَ ‏ ‏أَحَدَهُمَا وَلَمْ ‏ ‏يُشَمِّتْ ‏ ‏الْآخَرَ فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ ‏ ‏شَمَّتَّ ‏ ‏هَذَا وَلَمْ ‏ ‏تُشَمِّتْ ‏ ‏الْآخَرَ فَقَالَ ‏ ‏إِنَّ هَذَا حَمِدَ اللَّهَ وَإِنَّ هَذَا لَمْ يَحْمَدْ اللَّهَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سُلَيْمَانُ هُوَ التَّيْمِيُّ ‏","","",""],[2546,2546,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ هُوَ ابْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏عَطَسَ رَجُلٌ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَرْحَمُكَ اللَّهُ ثُمَّ عَطَسَ أُخْرَى فَقَالَ الرَّجُلُ مَزْكُومٌ ‏","","",""],[2547,2547,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ لَنَا ثَوْبٌ فِيهِ تَصَاوِيرُ فَجَعَلْتُهُ بَيْنَ يَدَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَنَهَانِي ‏ ‏أَوْ قَالَتْ فَكَرِهَهُ ‏ ‏قَالَتْ فَجَعَلْتُهُ وَسَائِدَ ‏","","",""],[2548,2548,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ الْعُكْلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَلَكَ لَا يَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ وَلَا جُنُبٌ ‏","","",""],[2549,2549,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ الْبَدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُسْلِمُ إِذَا أَنَفْقَ نَفَقَةً عَلَى أَهْلِهِ وَهُوَ ‏ ‏يَحْتَسِبُهَا ‏ ‏فَهِيَ لَهُ صَدَقَةٌ ‏","","",""],[2550,2550,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏مُوَرِّقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏قَفَلَ ‏ ‏تُلُقِّيَ بِي ‏ ‏وَبِالْحَسَنِ ‏ ‏أَوْ ‏ ‏بِالْحُسَيْنِ ‏ ‏قَالَ ‏ ‏وَأُرَاهُ قَالَ ‏ ‏الْحَسَنَ ‏ ‏فَحَمَلَنِي بَيْنَ يَدَيْهِ ‏ ‏وَالْحَسَنَ ‏ ‏وَرَاءَهُ قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏وَنَحْنُ عَلَى الدَّابَّةِ الَّتِي عَلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2551,2551,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏وَمَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏وَكَانَ أَمِيرًا عَلَى ‏ ‏الْكُوفَةِ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏قَيْسَ بْنَ سَعْدِ بْنِ عُبَادَةَ ‏ ‏فِي بَيْتِهِ فَأَذَّنَ الْمُؤَذِّنِ لِلصَّلَاةِ وَقُلْنَا ‏ ‏لِقَيْسٍ ‏ ‏قُمْ فَصَلِّ لَنَا فَقَالَ لَمْ أَكُنْ لِأُصَلِّيَ بِقَوْمٍ لَسْتُ عَلَيْهِمْ بِأَمِيرٍ فَقَالَ رَجُلٌ لَيْسَ بِدُونِهِ يُقَالُ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ حَنْظَلَةَ بْنِ الْغَسِيلِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ أَحَقُّ بِصَدْرِ دَابَّتِهِ وَصَدْرِ فِرَاشِهِ وَأَنْ يَؤُمَّ فِي ‏ ‏رَحْلِهِ ‏ ‏قَالَ ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عِنْدَ ذَاكَ ‏ ‏يَا فُلَانُ لِمَوْلًى لَهُ قُمْ فَصَلِّ لَهُمْ ‏","","",""],[2552,2552,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَمْزَةَ بْنِ عَمْرٍو الْأَسْلَمِيِّ ‏ ‏قَالَ وَقَدْ صَحِبَ أَبُوهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏ذِرْوَةِ ‏ ‏كُلِّ بَعِيرٍ شَيْطَانٌ فَإِذَا رَكِبْتُمُوهَا فَسَمُّوا اللَّهَ وَلَا تُقَصِّرُوا عَنْ حَاجَاتِكُمْ ‏","","",""],[2553,2553,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ارْكَبُوا هَذِهِ الدَّوَابَّ سَالِمَةً وَلَا تَتَّخِذُوهَا كَرَاسِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ ‏ ‏إِلَّا أَنَّهُ يُخَالِفُ ‏ ‏شَبَابَةَ ‏ ‏فِي شَيْءٍ ‏","","",""],[2554,2554,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّفَرُ قِطْعَةٌ مِنْ الْعَذَابِ يَمْنَعُ أَحَدَكُمْ نَوْمَهُ وَطَعَامَهُ وَشَرَابَهُ فَإِذَا قَضَى ‏ ‏نَهْمَتَهُ ‏ ‏مِنْ وَجْهِهِ فَلْيُعَجِّلْ الرَّجْعَةَ إِلَى أَهْلِهِ ‏","","",""],[2555,2555,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي كَعْبٍ أَبُو الْحَسَنِ الْعَبْدِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ مَيْسَرَةَ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ يَا نَبِيَّ اللَّهِ إِنِّي أُرِيدُ السَّفَرَ فَقَالَ لَهُ مَتَى قَالَ غَدًا إِنْ شَاءَ اللَّهُ قَالَ فَأَتَاهُ فَأَخَذَ بِيَدِهِ فَقَالَ لَهُ ‏ ‏فِي حِفْظِ اللَّهِ وَفِي كَنَفِهِ زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ لَكَ ذَنْبَكَ وَوَجَّهَكَ لِلْخَيْرِ أَيْنَمَا تَوَخَّيْتَ ‏ ‏أَوْ أَيْنَمَا تَوَجَّهْتَ شَكَّ ‏ ‏سَعِيدٌ ‏ ‏فِي إِحْدَى الْكَلِمَتَيْنِ ‏","","",""],[2556,2556,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ هُوَ الْأَحْوَلُ ‏ ‏قَالَ وَثَبَّتَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَافَرَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏وَعْثَاءِ ‏ ‏السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ ‏ ‏وَالْحَوْرِ ‏ ‏بَعْدَ ‏ ‏الْكَوْرِ ‏ ‏وَدَعْوَةِ الْمَظْلُومِ وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ ‏","","",""],[2557,2557,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ الْبَارِقِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَافَرَ فَرَكِبَ رَاحِلَتَهُ كَبَّرَ ثَلَاثًا وَيَقُولُ ‏ { ‏سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ ‏} ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ فِي سَفَرِي هَذَا الْبِرَّ وَالتَّقْوَى وَمِنْ الْعَمَلِ مَا ‏ ‏تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا السَّفَرَ وَاطْوِ لَنَا بُعْدَ الْأَرْضِ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اللَّهُمَّ اصْحَبْنَا فِي سَفَرِنَا وَاخْلُفْنَا فِي أَهْلِنَا بِخَيْرٍ ‏","","",""],[2558,2558,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا صَعِدْنَا كَبَّرْنَا وَإِذَا هَبَطْنَا سَبَّحْنَا ‏","","",""],[2559,2559,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَرَّاحِ ‏ ‏مَوْلَى ‏ ‏أَمِّ حَبِيبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعِيرُ الَّتِي فِيهَا الْجَرَسُ لَا تَصْحَبُهَا الْمَلَائِكَةُ ‏","","",""],[2560,2560,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رِفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ ‏","","",""],[2561,2561,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ فَسَمِعَ لَعْنَةً فَقَالَ ‏ ‏مَا هَذَا قَالُوا فُلَانَةُ لَعَنَتْ رَاحِلَتَهَا فَقَالَ ضَعُوا عَنْهَا فَإِنَّهَا مَلْعُونَةٌ قَالَ فَوَضَعُوا عَنْهَا قَالَ ‏ ‏عِمْرَانُ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهَا نَاقَةً ‏ ‏وَرْقَاءَ ‏","","",""],[2562,2562,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرْ الْمَرْأَةُ سَفَرًا ثَلَاثَةَ أَيَّامٍ فَصَاعِدًا إِلَّا وَمَعَهَا أَبُوهَا أَوْ أَخُوهَا أَوْ زَوْجُهَا أَوْ ذُو مَحْرَمٍ مِنْهَا ‏","","",""],[2563,2563,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْهَيْثَمُ بْنُ جَمِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ هُوَ ابْنُ مُحَمَّدٍ الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ لَمْ يَسْرِ رَاكِبٌ بِلَيْلٍ وَحْدَهُ أَبَدًا ‏","","",""],[2564,2564,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ إِسْحَقَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏خَوْلَةَ بِنْتِ حَكِيمٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّ أَحَدَكُمْ إِذَا نَزَلَ مَنْزِلًا قَالَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ يَضُرَّهُ فِي ذَلِكَ الْمَنْزِلِ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْهُ ‏","","",""],[2565,2565,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا نَزَلَ مَنْزِلًا لَمْ يَرْتَحِلْ مِنْهُ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ أَوْ يُوَدِّعَ الْمَنْزِلَ بِرَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏عُثْمَانُ بْنُ سَعْدٍ ‏ ‏ضَعِيفٌ ‏","","",""],[2566,2566,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ الْبَارِقِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَجَعَ مِنْ سَفَرِهِ قَالَ ‏ ‏آيِبُونَ ‏ ‏إِنْ شَاءَ اللَّهُ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ ‏","","",""],[2567,2567,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ رَجُلًا إِذَا أَخَذَ مَضْجَعَهُ أَنْ يَقُولَ ‏ ‏اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ وَوَجَّهْتُ وَجْهِي إِلَيْكَ وَفَوَّضْتُ أَمْرِي إِلَيْكَ وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ رَغْبَةً وَرَهْبَةً إِلَيْكَ لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَنَبِيِّكَ الَّذِي أَرْسَلْتَ فَإِنْ مَاتَ مَاتَ عَلَى ‏ ‏الْفِطْرَةِ ‏","","",""],[2568,2568,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ ‏ ‏بِدَاخِلَةِ إِزَارِهِ ‏ ‏فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ فِيهِ وَلْيَقُلْ اللَّهُمَّ بِكَ وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ اللَّهُمَّ إِنْ أَمْسَكْتَ نَفْسِي فَاغْفِرْ لَهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ ‏","","",""],[2569,2569,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى وَضَعَ قَدَمَهُ بَيْنِي وَبَيْنَ ‏ ‏فَاطِمَةَ ‏ ‏فَعَلَّمَنَا مَا نَقُولُ إِذَا أَخَذْنَا مَضَاجِعَنَا ثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً وَثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً وَأَرْبَعًا وَثَلَاثِينَ تَكْبِيرَةً ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏فَمَا تَرَكْتُهَا بَعْدُ فَقَالَ لَهُ رَجُلٌ وَلَا لَيْلَةَ ‏ ‏صِفِّينَ ‏ ‏قَالَ وَلَا لَيْلَةَ ‏ ‏صِفِّينَ ‏","","",""],[2570,2570,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ ‏ ‏النُّشُورُ ‏","","",""],[2571,2571,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْحِزَامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَيْرُ بْنُ هَانِىءٍ الْعَنْسِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جُنَادَةُ بْنُ أَبِي أُمَيَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَادَةُ بْنُ الصَّامِتِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏تَعَارَّ ‏ ‏مِنْ اللَّيْلِ فَقَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ثُمَّ قَالَ رَبِّ اغْفِرْ لِي ‏ ‏أَوْ قَالَ ثُمَّ دَعَا ‏ ‏اسْتُجِيبَ لَهُ فَإِنْ عَزَمَ فَتَوَضَّأَ ثُمَّ صَلَّى قُبِلَتْ صَلَاتُهُ ‏","","",""],[2572,2572,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصْبَحَ قَالَ ‏ ‏أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ وَكَلِمَةِ الْإِخْلَاصِ وَدِينِ نَبِيِّنَا ‏ ‏مُحَمَّدٍ ‏ ‏وَمِلَّةِ أَبِينَا ‏ ‏إِبْرَاهِيمَ ‏ ‏حَنِيفًا مُسْلِمًا ‏","","",""],[2573,2573,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ مُرْنِي بِشَيْءٍ أَقُولُهُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ قَالَ ‏ ‏قُلْ اللَّهُمَّ ‏ ‏فَاطِرَ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ قَالَ قُلْهُ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ وَإِذَا أَخَذْتَ مَضْجَعَكَ ‏","","",""],[2574,2574,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ هُوَ ابْنُ أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي مَرْحُومٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ ثَوْبًا فَقَالَ الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[2575,2575,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏أَوْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقُلْ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ فَلْيَقُلْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ ‏","","",""],[2576,2576,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَزْهَرُ بْنُ سِنَانٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏فَلَقِيتُ بِهَا أَخِي ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَحَدَّثَنِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ دَخَلَ السُّوقَ فَقَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ كَتَبَ اللَّهُ لَهُ أَلْفَ أَلْفِ حَسَنَةٍ وَمَحَا عَنْهُ أَلْفَ أَلْفِ سَيِّئَةٍ وَرَفَعَ لَهُ أَلْفَ أَلْفِ دَرَجَةٍ ‏ ‏قَالَ ‏ ‏فَقَدِمْتُ ‏ ‏خُرَاسَانَ ‏ ‏فَلَقِيتُ ‏ ‏قُتَيْبَةَ بْنَ مُسْلِمٍ ‏ ‏فَقُلْتُ ‏ ‏إِنِّي أَتَيْتُكَ بِهَدِيَّةٍ فَحَدَّثْتُهُ فَكَانَ يَرْكَبُ فِي مَوْكِبِهِ فَيَأْتِي السُّوقَ فَيَقُومُ فَيَقُولُهَا ثُمَّ يَرْجِعُ ‏","","",""],[2577,2577,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[2578,2578,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي زَكَرِيَّا الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ تُدْعَوْنَ يَوْمَ الْقِيَامَةِ بِأَسْمَائِكُمْ وَأَسْمَاءِ آبَائِكُمْ فَأَحْسِنُوا أَسْمَاءَكُمْ ‏","","",""],[2579,2579,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ الْأَسْمَاءِ إِلَى اللَّهِ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏","","",""],[2580,2580,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏الرُّكَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ نُسَمِّيَ أَرِقَّاءَنَا أَرْبَعَةَ أَسْمَاءٍ أَفْلَحُ وَنَافِعٌ وَرَبَاحٌ وَيَسَارٌ ‏","","",""],[2581,2581,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ هُوَ ابْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أُمَّ عَاصِمٍ ‏ ‏كَانَ يُقَالُ لَهَا ‏ ‏عَاصِيَةُ ‏ ‏فَسَمَّاهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمِيلَةَ ‏","","",""],[2582,2582,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ اسْمُ ‏ ‏زَيْنَبَ ‏ ‏بَرَّةَ ‏ ‏فَسَمَّاهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏","","",""],[2583,2583,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏الطُّفَيْلِ ‏ ‏أَخِي ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ مِنْ الْمُشْرِكِينَ لِرَجُلٍ مِنْ الْمُسْلِمِينَ نِعْمَ الْقَوْمُ أَنْتُمْ لَوْلَا أَنَّكُمْ تَقُولُونَ مَا شَاءَ اللَّهُ وَشَاءَ ‏ ‏مُحَمَّدٌ ‏ ‏فَسَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَقُولُوا مَا شَاءَ اللَّهُ وَشَاءَ ‏ ‏مُحَمَّدٌ ‏ ‏وَلَكِنْ قُولُوا مَا شَاءَ اللَّهُ ثُمَّ شَاءَ ‏ ‏مُحَمَّدٌ ‏","","",""],[2584,2584,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُوا ‏ ‏لِحَائِطِ ‏ ‏الْعِنَبِ الْكَرْمُ إِنَّمَا الْكَرْمُ الرَّجُلُ الْمُسْلِمُ ‏","","",""],[2585,2585,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ غُلَامٌ يَسُوقُ بِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدًا سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[2586,2586,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏بَهْزُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ لِلَّذِي يُحَدِّثُ فَيَكْذِبُ لِيُضْحِكَ بِهِ الْقَوْمَ وَيْلٌ لَهُ وَيْلٌ لَهُ ‏","","",""],[2587,2587,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَدَّقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمَيَّةَ بْنَ أَبِي الصَّلْتِ ‏ ‏فِي بَيْتَيْنِ مِنْ الشِّعْرِ فَقَالَ ‏ ‏رَجُلٌ وَثَوْرٌ تَحْتَ رِجْلِ يَمِينِهِ ‏ ‏وَالنَّسْرُ لِلْأُخْرَى وَلَيْثٌ مُرْصَدُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ ‏ ‏وَالشَّمْسُ تَطْلُعُ كُلَّ آخِرِ لَيْلَةٍ ‏ ‏حَمْرَاءَ يُصْبِحُ لَوْنُهَا يَتَوَرَّدُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ قَالَ ‏ ‏تَأْبَى فَمَا تَطْلُعُ لَنَا فِي رِسْلِهَا ‏ ‏إِلَّا مُعَذَّبَةً وَإِلَّا تُجْلَدُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[2588,2588,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ هُوَ ابْنُ سَعْدٍ ‏ ‏أَخْبَرَنِي أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ بْنِ عَبْدِ يَغُوثَ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ الشِّعْرِ حِكْمَةً ‏","","",""],[2589,2589,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا ‏ ‏أَوْ دَمًا ‏ ‏خَيْرٌ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[2590,2590,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا ‏ ‏يُفَقِّهْهُ فِي الدِّينِ ‏","","",""],[2591,2591,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ هُوَ ابْنُ سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الصِّحَّةَ وَالْفَرَاغَ نِعْمَتَانِ مِنْ نِعَمِ اللَّهِ ‏ ‏مَغْبُونٌ ‏ ‏فِيهِمَا كَثِيرٌ مِنْ النَّاسِ ‏","","",""],[2592,2592,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ صُبَّ فِي أُذُنِهِ ‏ ‏الْآنُكُ ‏","","",""],[2593,2593,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏لِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُتْبِعْ النَّظْرَةَ النَّظْرَةَ فَإِنَّ الْأُولَى لَكَ وَالْآخِرَةَ عَلَيْكَ ‏","","",""],[2594,2594,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ فِي الْإِسْلَامِ لَا أَسْأَلُ عَنْهُ أَحَدًا قَالَ ‏ ‏اتَّقِ اللَّهَ ثُمَّ اسْتَقِمْ قَالَ قُلْتُ ثُمَّ أَيُّ شَيْءٍ قَالَ فَأَشَارَ إِلَى لِسَانِهِ ‏","","",""],[2595,2595,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ إِسْمَعِيلَ بْنِ مُجَمِّعٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مُرْنِي بِأَمْرٍ أَعْتَصِمُ بِهِ قَالَ ‏ ‏قُلْ ‏ ‏رَبِّيَ اللَّهُ ثُمَّ اسْتَقِمْ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ مَا أَكْثَرُ مَا ‏ ‏تَخَوَّفُ عَلَيَّ قَالَ فَأَخَذَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلِسَانِهِ ثُمَّ قَالَ هَذَا ‏","","",""],[2596,2596,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَيُّ الْإِسْلَامِ أَفْضَلُ قَالَ ‏ ‏مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏","","",""],[2597,2597,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَمَتَ نَجَا ‏","","",""],[2598,2598,"","","‏ ‏أَخْبَرَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ مَا الْغِيبَةُ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قِيلَ وَإِنْ كَانَ فِي أَخِي مَا أَقُولُ قَالَ فَإِنْ كَانَ فِيهِ فَقَدْ اغْتَبْتَهُ وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[2599,2599,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏إِدْرِيسَ الْأَوْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَرْفَعُ الْحَدِيثَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ شَرَّ ‏ ‏الرَّوَايَا ‏ ‏رَوَايَا الْكَذِبِ وَلَا يَصْلُحُ مِنْ الْكَذِبِ جِدٌّ وَلَا هَزْلٌ وَلَا يَعِدُ الرَّجُلُ ابْنَهُ ثُمَّ لَا يُنْجِزُ لَهُ إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ وَإِنَّهُ يُقَالُ لِلصَّادِقِ صَدَقَ وَبَرَّ وَيُقَالُ لِلْكَاذِبِ كَذَبَ وَفَجَرَ وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا وَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا وَإِنَّهُ قَالَ لَنَا هَلْ أُنَبِّئُكُمْ مَا الْعَضْهُ وَإِنَّ الْعَضْهَ هِيَ ‏ ‏النَّمِيمَةُ ‏ ‏الَّتِي تُفْسِدُ بَيْنَ النَّاسِ ‏","","",""],[2600,2600,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏","","",""]];
